2	 * The excerpt an event hit carries: a window of `chars` characters from the
3	 * event's rendered text, centred on the first occurrence of any matched term
4	 * (case-insensitive), or the head of the text when no term occurs. Elisions
5	 * are marked so a model can tell an excerpt from a whole.
6	 *
7	 * Why a window and not the whole event: the published alternative this unit
8	 * was measured against (claude.ai's `conversation_search`) returns ~200-360-word
9	 * chunks, and on this project's store that size carried the answer literal on
10	 * 48 of 56 recorded queries at ~1.7k tokens per five hits — a payload the
11	 * model can answer from without a fetch (`reports/metrics/window-regime-and-retrieval-unit-report.md` §7).
12	 */
13	export function excerptAround(text: string, terms: readonly string[], chars: number, anchor: 'first' | 'rarest' = 'first'): string {
14	  if (text.length <= chars) return text;
15	  const lower = text.toLowerCase();
16	  let at = -1;
17	  for (const term of terms) {
18	    const idx = lower.indexOf(String(term).toLowerCase());
19	    if (idx >= 0 && (at < 0 || idx < at)) at = idx;
20	  }
21	  // Isolated experimental repair: prefer the least frequent matched term. The
22	  // historical first-match anchor remains the default and size is unchanged.
23	  if (anchor === 'rarest') {
24	    const matches = [...new Set(terms.map((term) => term.toLowerCase()).filter(Boolean))].flatMap((term) => {
25	      const start = lower.indexOf(term);
26	      if (start < 0) return [];
27	      let count = 0;
28	      let offset = start;
29	      while (offset >= 0) { count++; offset = lower.indexOf(term, offset + term.length); }
30	      return [{ start, count, length: term.length }];
31	    });
32	    matches.sort((a, b) => a.count - b.count || b.length - a.length || a.start - b.start);
33	    at = matches[0]?.start ?? -1;
34	  }
35	  let start = at < 0 ? 0 : Math.max(0, at - Math.floor(chars / 2));
36	  if (start + chars > text.length) start = Math.max(0, text.length - chars);
37	  const end = Math.min(text.length, start + chars);
38	  return `${start > 0 ? '…' : ''}${text.slice(start, end)}${end < text.length ? '…' : ''}`;
39	}
