230	    // or the root would swallow every event and the phase that did the work
231	    // would vanish from the hit list.
232	    // Ordering, however, uses the BEST rank of any branch holding the event: the
233	    // pool's relevance is a property of the event's context, not of the label it
234	    // is filed under, and tie-breaking on a file node's rank would push the top
235	    // phase's events below those of unrelated branches.
236	    type Entry = { branch: SummaryHit; rank: number; bestRank: number; seq: number; score: number; width: number; terms: string[] };
237	    const scored = new Set<NodeId>();
238	    const bySeq = new Map<number, Entry>();
239	    branches.forEach((branch, rank) => {
240	      const node = this.store.getNode(branch.nodeId);
241	      if (node === null) return;
242	      const span = nodeSpan(node);
243	      if (span === null) return;
244	      const center = this.findRelevantCenter(query, [span]);
245	      if (center.scores.length > 0) scored.add(branch.nodeId);
246	      const width = span.end - span.start;
247	      for (const { seq, score } of center.scores) {
