 * each) — the real s1 event store died with eval/ at 7d459f9. So this measures
 * chunker/ranker CHOICE on that corpus; it is not full-event retrieval, and the
 * absolute rates are optimistic vs a store of whole multi-KB events. What it
 * DOES settle is the relative question the user posed: does an off-the-shelf
 * pipeline, swept over its own parameters, beat the bespoke fixed-window unit —
 * and which configuration wins.
 *
 * RERUN
 * -----
 *   cd experiments/rung-0a-excerpt-window && npm install
 *   node offtheshelf-sweep.mjs
 * The vector/semantic arms need the MiniLM model. First run downloads it
 * (~90MB) and caches under node_modules/@xenova; if it cannot load (offline),
 * those arms are reported SKIPPED rather than faked. Deterministic given the
 * model + fixtures.
 * ============================================================================
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { execSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { RecursiveCharacterTextSplitter, TokenTextSplitter } from '@langchain/textsplitters';
import bm25Factory from 'wink-bm25-text-search';
import nlp from 'wink-nlp-utils';

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = join(HERE, '..', '..');
const CACHE = join(HERE, 'fixtures');
const OUT_DIR = join(REPO, 'reports', 'metrics', 'excerpt-window-0a');
const FIXTURE_COMMIT = '7d459f9^';
const FIXTURE_BASE = 'eval/fixtures/transplant/s1/e1b289c32f40';
const FILES = ['questions.json', 'questions-deep.json', 'questions-overflow.json'];
const TOPK = [1, 3, 5];
const EST_TOK = (s) => Math.round(s.length / 4);

// --------------------------------------------------------------------------
// Fixtures / corpus
// --------------------------------------------------------------------------
function gitSha() {
  try { return execSync('git rev-parse HEAD', { cwd: REPO }).toString().trim(); } catch { return null; }
}
function ensureFixtures() {
  if (!existsSync(CACHE)) mkdirSync(CACHE, { recursive: true });
  for (const f of FILES) {
    const dst = join(CACHE, f);
    if (existsSync(dst)) continue;
    const stem = f.replace('.json', '');
    writeFileSync(dst, execSync(`git show ${FIXTURE_COMMIT}:${FIXTURE_BASE}/${stem}.json`, { cwd: REPO, maxBuffer: 1 << 24 }));
  }
}
function loadCorpus() {
  ensureFixtures();
  const docs = [];
  const seen = new Set();
  const perFile = {};
  for (const f of FILES) {
    const d = JSON.parse(readFileSync(join(CACHE, f), 'utf8'));
    const qs = d.questions ?? [];
    perFile[f] = qs.length;
    for (const q of qs) {
      const key = `${q.id}::${q.wide_context ?? ''}`;
      if (seen.has(key)) continue;
      seen.add(key);
      docs.push({ id: q.id, text: q.wide_context ?? '', question: q.question ?? '', literals: q.answer_literals ?? [] });
    }
  }
  return { docs, perFile };
}

// --------------------------------------------------------------------------
// Embeddings (MiniLM via transformers.js), cached by exact string
// --------------------------------------------------------------------------
async function makeEmbedder() {
  let pipe;
  try {
    const t = await import('@xenova/transformers');
    t.env.allowRemoteModels = true;
    pipe = await t.pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2');
  } catch (e) {
    return { ok: false, reason: e.message, embed: null };
  }
  const cache = new Map();
  const embed = async (text) => {
    const key = text;
    const hit = cache.get(key);
    if (hit) return hit;
    const out = await pipe(text, { pooling: 'mean', normalize: true });
    const vec = Float32Array.from(out.data);
    cache.set(key, vec);
    return vec;
  };
  return { ok: true, embed };
}
function cosine(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }

// --------------------------------------------------------------------------
// Sentence utilities (shared by semantic + sentence-window chunkers)
// --------------------------------------------------------------------------
function splitSentences(text) {
  return text
    .split(/(?<=[.!?;])\s+|\n+/)
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
}
function percentile(sorted, p) {
  if (sorted.length === 0) return 0;
  const idx = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[idx];
}

// --------------------------------------------------------------------------
// Chunkers — each returns [{ id, indexText, returnText, docId }]
// indexText is what the ranker scores; returnText is what the model receives.
// --------------------------------------------------------------------------
async function chunkRecursive(docs, { chunkSize, chunkOverlap }) {
  const splitter = new RecursiveCharacterTextSplitter({ chunkSize, chunkOverlap });
  return flatten(docs, async (doc) => splitter.splitText(doc.text));
}
async function chunkToken(docs, { chunkSize, chunkOverlap }) {
  const splitter = new TokenTextSplitter({ chunkSize, chunkOverlap });
  return flatten(docs, async (doc) => splitter.splitText(doc.text));
}
async function flatten(docs, splitFn) {
  const chunks = [];
  let n = 0;
  for (const doc of docs) {
    for (const piece of await splitFn(doc)) {
      chunks.push({ id: n++, indexText: piece, returnText: piece, docId: doc.id });
    }
  }
  return chunks;
}
// Standard semantic chunking: embed each sentence (with a ±1 buffer), split
// where the cosine distance between consecutive sentences exceeds the P-th
// percentile of that document's distances.
async function chunkSemantic(docs, { percentileP }, embed) {
  const chunks = [];
  let n = 0;
  for (const doc of docs) {
    const sents = splitSentences(doc.text);
    if (sents.length <= 1) { chunks.push({ id: n++, indexText: doc.text, returnText: doc.text, docId: doc.id }); continue; }
    const buffered = sents.map((s, i) => [sents[i - 1] ?? '', s, sents[i + 1] ?? ''].join(' ').trim());
    const embs = [];
    for (const b of buffered) embs.push(await embed(b));
    const dist = [];
    for (let i = 0; i < embs.length - 1; i++) dist.push(1 - cosine(embs[i], embs[i + 1]));
    const thr = percentile([...dist].sort((a, b) => a - b), percentileP);
    let cur = [sents[0]];
    for (let i = 0; i < dist.length; i++) {
      if (dist[i] > thr) { chunks.push(mkChunk(n++, cur.join(' '), doc.id)); cur = []; }
      cur.push(sents[i + 1]);
    }
    if (cur.length) chunks.push(mkChunk(n++, cur.join(' '), doc.id));
  }
  return chunks;
}
function mkChunk(id, text, docId) { return { id, indexText: text, returnText: text, docId }; }
// Sentence-window / parent-document: rank a single sentence, but RETURN that
// sentence plus `window` neighbours on each side.
function chunkSentenceWindow(docs, { window }) {
  const chunks = [];
  let n = 0;
  for (const doc of docs) {
    const sents = splitSentences(doc.text);
    for (let i = 0; i < sents.length; i++) {
      const lo = Math.max(0, i - window), hi = Math.min(sents.length, i + window + 1);
      chunks.push({ id: n++, indexText: sents[i], returnText: sents.slice(lo, hi).join(' '), docId: doc.id });
    }
  }
  return chunks;
}

// --------------------------------------------------------------------------
// Rankers — return chunk ids ranked best-first for a query
// --------------------------------------------------------------------------
function bm25Rank(chunks, questions) {
  const engine = bm25Factory();
  engine.defineConfig({ fldWeights: { text: 1 } });
  engine.definePrepTasks([nlp.string.lowerCase, nlp.string.tokenize0, nlp.tokens.removeWords, nlp.tokens.stem]);
  for (const c of chunks) engine.addDoc({ text: c.indexText || ' ' }, c.id);
  engine.consolidate();
  const ranked = {};
  for (const q of questions) {
    let res = [];
    try { res = engine.search(q.question); } catch { res = []; }
    ranked[q.id] = res.map(([id]) => id);
  }
  return ranked;
}
async function vectorRank(chunks, questions, embed) {
  const chunkEmb = [];
  for (const c of chunks) chunkEmb.push(await embed(c.indexText || ' '));
  const ranked = {};
  for (const q of questions) {
    const qe = await embed(q.question);
    const scored = chunks.map((c, i) => [c.id, cosine(qe, chunkEmb[i])]);
    scored.sort((a, b) => b[1] - a[1]);
    ranked[q.id] = scored.map(([id]) => id);
  }
  return ranked;
}

// --------------------------------------------------------------------------
// Scoring: for a ranking, present-rate and returned-size at each top-k
// --------------------------------------------------------------------------
function scoreRanking(chunks, docs, ranked) {
  const byId = new Map(chunks.map((c) => [c.id, c]));
  const out = {};
  for (const k of TOPK) {
    let all = 0, any = 0, sz = 0;
    for (const doc of docs) {
      const ids = (ranked[doc.id] ?? []).slice(0, k);
      const text = ids.map((id) => byId.get(id)?.returnText ?? '').join('\n');
      const lits = doc.literals;
      if (lits.length > 0 && lits.every((l) => text.includes(l))) all++;
      if (lits.some((l) => text.includes(l))) any++;
      sz += EST_TOK(text);
    }
    const nQ = docs.length;
    out[k] = {
      allPresentRate: +(all / nQ).toFixed(4), allPresentCount: all,
      anyPresentRate: +(any / nQ).toFixed(4),
      meanReturnedTokens: Math.round(sz / nQ),
    };
  }
  return out;
}

// --------------------------------------------------------------------------
// Sweep definition
// --------------------------------------------------------------------------
function chunkerConfigs() {
  const cfgs = [];
  for (const chunkSize of [256, 512, 1024]) for (const chunkOverlap of [0, 128])
    cfgs.push({ chunker: 'recursive', params: { chunkSize, chunkOverlap }, needsEmbed: false });
  for (const chunkSize of [128, 256]) for (const chunkOverlap of [0, 32])
    cfgs.push({ chunker: 'token', params: { chunkSize, chunkOverlap }, needsEmbed: false });
  for (const percentileP of [90, 95])
    cfgs.push({ chunker: 'semantic', params: { percentileP }, needsEmbed: true });
  for (const window of [1, 2])
    cfgs.push({ chunker: 'sentence-window', params: { window }, needsEmbed: false });
  return cfgs;
}
async function buildChunks(cfg, docs, embed) {
  switch (cfg.chunker) {
    case 'recursive': return chunkRecursive(docs, cfg.params);
    case 'token': return chunkToken(docs, cfg.params);
    case 'semantic': return chunkSemantic(docs, cfg.params, embed);
    case 'sentence-window': return chunkSentenceWindow(docs, cfg.params);
    default: throw new Error(`unknown chunker ${cfg.chunker}`);
  }
}
const cfgLabel = (cfg) => `${cfg.chunker}(${Object.entries(cfg.params).map(([k, v]) => `${k}=${v}`).join(',')})`;

// --------------------------------------------------------------------------
// Main
// --------------------------------------------------------------------------
async function main() {
  const { docs, perFile } = loadCorpus();
  const emb = await makeEmbedder();
  const rankers = ['bm25', ...(emb.ok ? ['vector'] : [])];
  const cells = [];

  for (const cfg of chunkerConfigs()) {
    if (cfg.needsEmbed && !emb.ok) {
      cells.push({ chunker: cfgLabel(cfg), ranker: 'n/a', skipped: `needs MiniLM (unavailable: ${emb.reason})` });
      continue;
    }
    const chunks = await buildChunks(cfg, docs, emb.embed);
    const nChunks = chunks.length;
    const bm25Ranked = bm25Rank(chunks, docs);
    const rankings = { bm25: bm25Ranked };
    if (emb.ok) rankings.vector = await vectorRank(chunks, docs, emb.embed);
    for (const ranker of rankers) {
      const perK = scoreRanking(chunks, docs, rankings[ranker]);
      for (const k of TOPK) {
        cells.push({
          chunker: cfgLabel(cfg), chunkerKind: cfg.chunker, params: cfg.params,
          ranker, topK: k, nChunks,
          allPresentRate: perK[k].allPresentRate, allPresentCount: perK[k].allPresentCount,
          anyPresentRate: perK[k].anyPresentRate, meanReturnedTokens: perK[k].meanReturnedTokens,
        });
      }
    }
    process.stderr.write('.');
  }
  process.stderr.write('\n');

  const scored = cells.filter((c) => !c.skipped);
  scored.sort((a, b) => b.allPresentRate - a.allPresentRate || a.meanReturnedTokens - b.meanReturnedTokens);

  const out = {
    runId: process.env.RUN_ID ?? `excerpt-window-0a-offtheshelf-${new Date().toISOString().slice(0, 10)}`,
    armId: 'offtheshelf-chunk-retrieve-rank@v1',
    rung: '0a', offline: true,
    stack: {
      chunkers: 'LangChain RecursiveCharacterTextSplitter/TokenTextSplitter; semantic percentile-breakpoint (MiniLM); sentence-window',
      rankers: 'BM25 (wink-bm25-text-search); dense vector (Xenova/all-MiniLM-L6-v2 cosine)',
      embedModel: emb.ok ? 'Xenova/all-MiniLM-L6-v2' : null,
    },
    judge: 'literal-substring-match over union of top-k returned chunks',
    commit: gitSha(), fixtureCommit: FIXTURE_COMMIT, date: new Date().toISOString(),
    caveat: 'Corpus = pooled answer-windowed wide_context slices (<=~2.1KB); real s1 event store deleted at 7d459f9. Absolute rates optimistic; relative chunker/ranker comparison is the deliverable.',
    corpus: { files: perFile, docs: docs.length },
    embedderAvailable: emb.ok, embedderSkipReason: emb.ok ? null : emb.reason,
    best: scored[0] ?? null,
    cells,
  };
  if (!existsSync(OUT_DIR)) mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(join(OUT_DIR, 'results-offtheshelf.json'), JSON.stringify(out, null, 2));

  printSummary(out, scored);
  console.log(`\nwrote ${join('reports', 'metrics', 'excerpt-window-0a', 'results-offtheshelf.json')}`);
}

function printSummary(out, scored) {
  console.log(`corpus: ${out.corpus.docs} pooled docs | rankers: ${out.embedderAvailable ? 'bm25, vector' : 'bm25 (vector SKIPPED: ' + out.embedderSkipReason + ')'}`);
  console.log(`\nTop 10 configurations by allPresentRate (tie-break: fewer tokens):`);
  console.log('rank  allPresent  tokens  topK  ranker  chunker');
  scored.slice(0, 10).forEach((c, i) => {
    console.log(
      `${String(i + 1).padStart(2)}    ${(c.allPresentRate * 100).toFixed(1).padStart(5)}%   ${String(c.meanReturnedTokens).padStart(5)}   k=${c.topK}   ${c.ranker.padEnd(6)}  ${c.chunker}`,
    );
  });
  // Best per chunker family, at k=5, for a fair cross-family read.
  console.log(`\nBest per chunker family (any k/ranker):`);
  const fams = [...new Set(scored.map((c) => c.chunkerKind))];
  for (const fam of fams) {
    const best = scored.filter((c) => c.chunkerKind === fam)[0];
    console.log(`  ${fam.padEnd(16)} ${(best.allPresentRate * 100).toFixed(1)}%  ${best.meanReturnedTokens}t  (${best.ranker}, k=${best.topK}, ${best.chunker})`);
  }
}

main().catch((e) => { console.error(e); process.exit(1); });

