// document, removing retrieval/ranking error so the result isolates the chunker
// — apples-to-apples with the bespoke sweep, which was handed the right doc.
function scoreRanking(chunks, docs, ranked, oracle = false) {
  const byId = new Map(chunks.map((c) => [c.id, c]));
  const out = {};
  for (const k of TOPK) {
    let all = 0, any = 0, sz = 0;
    for (const doc of docs) {
      let ids = ranked[doc.id] ?? [];
      if (oracle) ids = ids.filter((id) => byId.get(id)?.docId === doc.id);
      ids = ids.slice(0, k);
      const text = ids.map((id) => byId.get(id)?.returnText ?? '').join('\n');
      const lits = doc.literals;
      if (lits.length > 0 && lits.every((l) => text.includes(l))) all++;
