async function vectorRank(chunks, questions, embed) {
  const chunkEmb = [];
  for (const c of chunks) chunkEmb.push(await embed(c.indexText || ' '));
  const ranked = {};
  for (const q of questions) {
    const qe = await embed(q.question);
    const scored = chunks.map((c, i) => [c.id, cosine(qe, chunkEmb[i])]);
    scored.sort((a, b) => b[1] - a[1]);
    ranked[q.id] = scored.map(([id]) => id);
  }
  return ranked;
}
// 2nd stage: cross-encoder re-scores the first-stage top-N, prepends the
// reranked order (remaining base order kept as the tail).
async function rerankRank(chunks, questions, baseRanked, reranker) {
  const byId = new Map(chunks.map((c) => [c.id, c]));
  const ranked = {};
  for (const q of questions) {
    const base = baseRanked[q.id] ?? [];
    const head = base.slice(0, RERANK_N);
    const passages = head.map((id) => byId.get(id)?.indexText || ' ');
    const scores = await reranker.score(q.question, passages);
    const reordered = head.map((id, i) => [id, scores[i]]).sort((a, b) => b[1] - a[1]).map(([id]) => id);
    ranked[q.id] = [...reordered, ...base.slice(RERANK_N)];
  }
  return ranked;
}

