/**
 * ============================================================================
 * EXPERIMENT: Rung 0e Phase 2 — style-tailored retriever benchmark (repo corpus)
 * ============================================================================
 *
 * Source plan: reports/hypothesis-test-ladder.md §"Rung 0 · 0e".
 * Results: reports/metrics/rung-0e-retrievers/results-repo-benchmark.json
 *
 * WHY
 * ---
 * The s1 slice corpus is homogeneous, so it cannot reveal per-style strengths —
 * and per-style strength is the whole premise of interleaving/routing. This
 * benchmark uses the CONTEXT-TREE REPO ITSELF as the corpus and a question set
 * stratified BY RETRIEVER STYLE, each stratum with a verified ground-truth file.
 * Only a code repo lets the STRUCTURAL retriever (graft, real CLI) compete, so
 * this is where the "code-like questions want tree-sitter" idea is testable.
 *
 * STRATA (expected winner in parens)
 * ----------------------------------
 *   structural  (graft)  — callers / connections / structure
 *   literal     (grep/bm25) — an exact constant, value, or name
 *   semantic    (vector) — paraphrase, no shared identifiers
 *   fuzzy       (fuzzy)  — a misspelled symbol
 *
 * RETRIEVERS (all local/offline; graft is the REAL CLI per operator choice)
 * ------------------------------------------------------------------------
 *   graft   — `graft ask "<q>" --in packages/ --source`, parse path:L#-L# spans
 *   bm25    — wink-bm25-text-search over repo chunks
 *   grep    — deterministic: count of query terms present as substrings
 *   vector  — MiniLM cosine over repo chunks
 *   fuzzy   — trigram Jaccard over repo chunks
 * NB the HR2-INVARIANT: here graft is a retriever WE run and assemble, so
 * comparing/interleaving it is legitimate; the combination arms preserve each
 * source's own ranking (round-robin by rank) and never re-score a source.
 *
 * SCORING
 * -------
 * Each retriever returns a ranked list of units → dedup to files preserving
 * order → top-k. Metric: file-in-top-k rate (the ground-truth file appears in
 * the top-k retrieved files), per retriever, per stratum, at k ∈ {1,3,5}.
 *
 * COMBINATION ARMS (Phase 2 proper)
 * ---------------------------------
 *   best-single      — the strongest individual retriever overall (the bar)
 *   rrf              — reciprocal-rank fusion across retrievers (the refuted-shape arm)
 *   interleave       — round-robin by rank across retrievers (rank-preserving; operator's idea)
 *   router-oracle    — route each question to the retriever matching its TRUE stratum;
 *                      a CEILING for routing (a real router would classify the question)
 *
 * CAVEATS
 * -------
 * - Ground-truth is file-level (the answer's home file). A retriever that surfaces
 *   the right file but the wrong span still scores; span-level is left to a later pass.
 * - 16 questions, 4 per stratum — directional, not powered. Report per-stratum so a
 *   1-question swing is visible.
 * - Corpus = packages/*/src/**.ts (production source; tests/dist/experiments excluded),
 *   matched by `graft --in packages/`.
 *
 * RERUN: node repo-benchmark.mjs   (needs the real graft CLI on PATH + MiniLM model)
 * ============================================================================
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { execSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join, relative } from 'node:path';
import { RecursiveCharacterTextSplitter } from '@langchain/textsplitters';
import bm25Factory from 'wink-bm25-text-search';
import nlp from 'wink-nlp-utils';

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = join(HERE, '..', '..');
const OUT_DIR = join(REPO, 'reports', 'metrics', 'rung-0e-retrievers');
const TOPK = [1, 3, 5];
const CHUNK = { chunkSize: 800, chunkOverlap: 100 };
const STRATA = ['structural', 'literal', 'semantic', 'fuzzy'];
const EXPECTED = { structural: 'graft', literal: 'grep', semantic: 'vector', fuzzy: 'fuzzy' };

// ---- The style-tailored question set (ground-truth files verified before authoring) ----
const QUESTIONS = [
  // structural — callers / connections / structure (expect graft)
  { id: 'st1', stratum: 'structural', q: 'What functions call excerptAround?', file: 'packages/core/src/retrieve/retriever.ts' },
