// ---- retrievers: each returns a ranked list of file paths (deduped, order preserved) ----
export function dedupeFiles(ids, chunks) {
  const byId = new Map(chunks.map((c) => [c.id, c]));
  const seen = new Set(); const files = [];
  for (const id of ids) { const f = byId.get(id)?.file; if (f && !seen.has(f)) { seen.add(f); files.push(f); } }
  return files;
}
export function bm25Ranker(chunks) {
  const eng = bm25Factory();
  eng.defineConfig({ fldWeights: { text: 1 } });
  eng.definePrepTasks([nlp.string.lowerCase, nlp.string.tokenize0, nlp.tokens.removeWords, nlp.tokens.stem]);
  for (const c of chunks) eng.addDoc({ text: c.text || ' ' }, c.id);
  eng.consolidate();
  return (q) => { let r = []; try { r = eng.search(q); } catch { r = []; } return dedupeFiles(r.map(([id]) => Number(id)), chunks); };
}
export function grepRanker(chunks) {
  return (q) => {
    const ts = queryTerms(q).map((t) => t.toLowerCase());
    const scored = chunks.map((c) => { const low = c.text.toLowerCase(); let s = 0; for (const t of ts) if (low.includes(t)) s++; return [c.id, s]; });
    return dedupeFiles(scored.filter(([, s]) => s > 0).sort((a, b) => b[1] - a[1]).map(([id]) => id), chunks);
  };
}
export function fuzzyRanker(chunks) {
  const tri = chunks.map((c) => trigrams(c.text));
  return (q) => { const qt = trigrams(q); return dedupeFiles(chunks.map((c, i) => [c.id, jaccard(qt, tri[i])]).sort((a, b) => b[1] - a[1]).map(([id]) => id), chunks); };
}
export function vectorRanker(chunks, chunkEmb, embed) {
  return async (q) => { const qe = await embed(q); return dedupeFiles(chunks.map((c, i) => [c.id, cosine(qe, chunkEmb[i])]).sort((a, b) => b[1] - a[1]).map(([id]) => id), chunks); };
}
export function graftRanker() {
  return (q) => {
    let out = '';
    try { out = execSync(`graft ask ${JSON.stringify(q)} --in packages/ --source`, { cwd: REPO, maxBuffer: 1 << 24, timeout: 20000 }).toString(); } catch { return []; }
    const seen = new Set(); const files = [];
    for (const m of out.matchAll(/(packages\/[A-Za-z0-9_./-]+\.[A-Za-z0-9_]+):L?\d+/g)) {
      const f = m[1]; if (!f.includes('/dist/') && !f.includes('/test/') && !seen.has(f)) { seen.add(f); files.push(f); }
    }
    return files;
  };
}

