// ---- per-variant AssembledPrompt builders ----
function currentZones(t) {
  const s = stateAt(t);
  const blocks = [blk('A', 'A:system', TOK.system), blk('A', 'A:tools', TOK.tools)];
  const bp = ['A:tools'];
  for (let p = 0; p < s.closedPhases; p++) blocks.push(blk('B', `B:phase${p}`, TOK.summary)); // creation order, cached
  if (s.closedPhases > 0) bp.push(`B:phase${s.closedPhases - 1}`);
  for (const u of s.units.filter((u) => u.phase === s.openPhase)) blocks.push(blk('C', `C:${u.id}`, TOK.raw)); // rewritten each turn
  return { blocks, cacheBreakpoints: bp };
}
function flexRemix(t) {
  const s = stateAt(t);
  const blocks = [blk('A', 'A:system', TOK.system), blk('A', 'A:tools', TOK.tools)];
  const bp = ['A:tools'];
  // re-rank all units by a churning "relevance" (rotates each turn) → order changes after Zone A
  const order = s.units.map((u, i) => ({ u, r: (i * 7 + t * 13) % s.units.length }));
  order.sort((a, b) => a.r - b.r);
  let used = 0;
  for (const { u } of order) { if (used + TOK.summary > 0.4 * W) break; blocks.push(blk('F', `F:${u.id}`, TOK.summary)); used += TOK.summary; }
  return { blocks, cacheBreakpoints: bp };
}
function flexAppendSticky(t, softFrac) {
  const s = stateAt(t);
  // Zone A: system + steering + all user prompts, append-only
  const blocks = [blk('A', 'A:system', TOK.system), blk('A', 'A:steering', TOK.steering)];
  for (const p of s.userPrompts) blocks.push(blk('A', `A:user:${p}`, TOK.userPrompt));
  const bp = [`A:user:${s.userPrompts[s.userPrompts.length - 1]}`];
  // Flex buffer: creation order, sticky representation by age. Recent units raw; older summary; oldest ref.
  // Stable head = everything except the current (open) phase's units → secondary breakpoint there.
  const soft = softFrac * W;
  const flex = [];
  let used = 0;
  for (const u of s.units) {
    const age = s.openPhase - u.phase; // 0 = current phase (raw), grows with age
    const repTok = age === 0 ? TOK.raw : age <= 2 ? TOK.summary : TOK.ref; // sticky by age band
    flex.push({ id: `F:${u.id}`, tokens: repTok, stable: u.phase < s.openPhase });
    used += repTok;
  }
  // enforce soft target: if over, drop the OLDEST refs first (conservative: keep recent)
  while (used > soft && flex.length > 0 && !flex[0].stable === false) {
    // only drop stable (old) entries; never drop the open-phase raw (recent)
    const idx = flex.findIndex((f) => f.stable);
    if (idx < 0) break;
    used -= flex[idx].tokens; flex.splice(idx, 1);
  }
  let lastStable = null;
  for (const f of flex) { blocks.push(blk('F', f.id, f.tokens)); if (f.stable) lastStable = f.id; }
  if (lastStable) bp.push(lastStable); // secondary breakpoint after the stable head
  return { blocks, cacheBreakpoints: bp };
}

